// The kb-media cross-check against the JS originals, three ways:
//   - write: the Rust writer's bytes equal the JS writer's bytes for the same params,
//   - read:  the Rust receipt equals the JS reader's own receipt, string for string,
//   - refusals: every tampered file fails with the same sentence the JS reader raises.
// Fixtures are generated by gen-kb-fixtures.mjs and committed with the crate.
use kohane_decoder::json;
use kohane_decoder::parsers::kbmedia;
use std::fs;

fn fixture(name: &str) -> String {
    format!(
        "{}/tests/fixtures/kbmedia/{name}",
        env!("CARGO_MANIFEST_DIR")
    )
}

fn read_fixture(name: &str) -> Vec<u8> {
    fs::read(fixture(name)).unwrap_or_else(|e| panic!("cannot read fixture {name}: {e}"))
}

#[test]
fn write_matches_the_js_originals_byte_for_byte() {
    let cases = [
        ("kbs", "score-params.json", "js-score.kbs"),
        ("kbw", "wave-params.json", "js-wave.kbw"),
        ("kbv", "view-params.json", "js-view.kbv"),
        ("kbm", "mix-params.json", "js-mix.kbm"),
    ];
    for (kind, params_file, js_file) in cases {
        let params_text = fs::read_to_string(fixture(params_file)).unwrap();
        let params = json::parse(&params_text).unwrap();
        let bytes = match kind {
            "kbs" => kbmedia::write_kbs(&params),
            "kbw" => kbmedia::write_kbw(&params),
            "kbv" => kbmedia::write_kbv(&params),
            _ => kbmedia::write_kbm(&params),
        };
        let reference = read_fixture(js_file);
        assert_eq!(
            bytes, reference,
            "the {kind} writer drifted from the JS reference"
        );
    }
}

#[test]
fn read_matches_the_js_receipts_string_for_string() {
    let cases = [
        ("kbs", "js-score.kbs", "js-read-kbs.json"),
        ("kbw", "js-wave.kbw", "js-read-kbw.json"),
        ("kbv", "js-view.kbv", "js-read-kbv.json"),
        ("kbm", "js-mix.kbm", "js-read-kbm.json"),
    ];
    for (kind, container, receipt_file) in cases {
        let buf = read_fixture(container);
        let receipt = match kind {
            "kbs" => kbmedia::read_kbs(&buf),
            "kbw" => kbmedia::read_kbw(&buf),
            "kbv" => kbmedia::read_kbv(&buf),
            _ => kbmedia::read_kbm(&buf),
        }
        .unwrap();
        let expected = fs::read_to_string(fixture(receipt_file)).unwrap();
        assert_eq!(
            receipt.render(),
            expected,
            "the {kind} receipt differs from the JS reader's own receipt"
        );
    }
}

#[test]
fn refusals_carry_the_js_sentence() {
    let cases = [
        ("bad-note.kbs", 0u8),
        ("bad-velocity.kbs", 0),
        ("bad-wave.kbs", 0),
        ("notes-not-list.kbs", 0),
        ("bad-marker.kbs", 0),
        ("bad-version.kbs", 0),
        ("bad-json.kbs", 0),
        ("empty-buckets.kbw", 1),
        ("bad-bucket.kbw", 1),
        ("bad-rate.kbw", 1),
        ("bad-lanes.kbv", 2),
        ("palette-not-list.kbv", 2),
        ("unknown-route.kbm", 3),
        ("bad-track-gain.kbm", 3),
        ("bad-pan.kbm", 3),
        ("no-master.kbm", 3),
        ("bad-master-gain.kbm", 3),
    ];
    for (file, family) in cases {
        let buf = read_fixture(file);
        let err = match family {
            0 => kbmedia::read_kbs(&buf).unwrap_err(),
            1 => kbmedia::read_kbw(&buf).unwrap_err(),
            2 => kbmedia::read_kbv(&buf).unwrap_err(),
            _ => kbmedia::read_kbm(&buf).unwrap_err(),
        };
        let expected = fs::read_to_string(fixture(&format!("{file}.err.txt"))).unwrap();
        assert_eq!(err, expected, "{file} was refused with the wrong sentence");
    }
}
